#!/usr/bin/env python3
import os,json,time,base64,subprocess,urllib.request,urllib.parse
from pathlib import Path
RUN=Path.home()/".copytolive-chat-lokal"; TOKEN_FILE=RUN/"token"; STATE=RUN/"transport-v4-state.json"; LOG=RUN/"transport-v4.log"
BASE="http://127.0.0.1:8765"; TARGET_URL="https://chatgpt.com/c/6ab010ca-ee50-83ec-beea-b410c17211ba"
def log(*x):
 s=time.strftime("%Y-%m-%d %H:%M:%S")+" "+" ".join(map(str,x))
 with LOG.open("a",encoding="utf-8") as f:f.write(s+"\n")
def osa(sc,t=10):
 p=subprocess.run(["/usr/bin/osascript","-e",sc],capture_output=True,text=True,timeout=t)
 if p.returncode: raise RuntimeError((p.stderr or p.stdout).strip())
 return p.stdout.rstrip()
def b64js(s): return base64.b64encode(s.encode()).decode()
SCAN=r'''(() => {const t=document.body?.innerText||document.body?.textContent||"";const re=/\[\[CHATLOCAL_V4_REQUEST\]\]([A-Za-z0-9_-]+)\[\[\/CHATLOCAL_V4_REQUEST\]\]/g;const a=[];let m;while((m=re.exec(t)))a.push(m[1]);return JSON.stringify(a)})()'''
def target_tabs():
 b=b64js(SCAN); uq=TARGET_URL.replace("\\","\\\\").replace('"','\\"')
 sc=f'''tell application "Google Chrome"
 set outText to ""
 repeat with wi from 1 to count of windows
  repeat with ti from 1 to count of tabs of window wi
   try
    if URL of tab ti of window wi is "{uq}" then
     set r to execute tab ti of window wi javascript "eval(atob('{b}'))"
     set outText to outText & wi & "::CHATLOCALV4::" & ti & "::CHATLOCALV4::" & r & linefeed
    end if
   end try
  end repeat
 end repeat
 return outText
end tell'''
 out=osa(sc,8); rows=[]
 for line in out.splitlines():
  p=line.split("::CHATLOCALV4::",2)
  if len(p)==3:
   try: rows.append((int(p[0]),int(p[1]),json.loads(p[2])))
   except: pass
 return rows
def send_to_tab(wi,ti,text):
 payload=base64.b64encode(text.encode()).decode()
 js=rf'''(() => {{const text=new TextDecoder().decode(Uint8Array.from(atob("{payload}"),c=>c.charCodeAt(0)));const el=document.querySelector('#prompt-textarea,[contenteditable="true"][data-virtualkeyboard],[contenteditable="true"][data-testid="prompt-textarea"]');if(!el)return "NO_COMPOSER";el.focus();if(el.isContentEditable){{el.innerHTML="";document.execCommand("insertText",false,text)}}else{{el.value=text}}el.dispatchEvent(new InputEvent("input",{{bubbles:true,inputType:"insertText",data:text}}));setTimeout(()=>{{const b=document.querySelector('button[data-testid="send-button"],button[aria-label*="Send"],button[aria-label*="Kirim"]');if(b&&!b.disabled)b.click()}},350);return "SCHEDULED"}})()'''
 b=b64js(js); sc=f'''tell application "Google Chrome"
 try
  return execute tab {ti} of window {wi} javascript "eval(atob('{b}'))"
 on error errText
  return "SEND_ERROR: " & errText
 end try
end tell'''
 return osa(sc,8)
def kick_daemon():
 subprocess.run(["launchctl","kickstart","-k",f"gui/{os.getuid()}/com.copytolive.chat-lokal"],capture_output=True,text=True)
def local(req):
 tok=TOKEN_FILE.read_text().strip(); h={"Content-Type":"application/json","X-CopyToLive-Token":tok}
 def enqueue():
  q=urllib.request.Request(BASE+"/v1/enqueue",data=json.dumps(req,separators=(",",":")).encode(),method="POST",headers=h)
  with urllib.request.urlopen(q,timeout=10) as r:return json.load(r)
 try: en=enqueue()
 except Exception:
  kick_daemon();time.sleep(2);en=enqueue()
 qid=str(en.get("id") or req["id"]); deadline=time.time()+180
 while time.time()<deadline:
  try:
   q=urllib.request.Request(BASE+"/v1/result/"+urllib.parse.quote(qid,safe=""),headers={"X-CopyToLive-Token":tok})
   with urllib.request.urlopen(q,timeout=10) as r: st=json.load(r)
   if st.get("status") in ("done","error"): return st.get("result") or st
  except: pass
  time.sleep(.12)
 return {"ok":False,"id":req.get("id"),"error":"Timeout"}
def decode(s):
 try:
  s=s+"="*((4-len(s)%4)%4); x=json.loads(base64.urlsafe_b64decode(s).decode())
  return x if isinstance(x,dict) and x.get("id") and x.get("op") else None
 except:return None
try: state=json.loads(STATE.read_text()) if STATE.exists() else {}
except: state={}
seen=set(state.get("seen") or [])
log("V4_TARGET_START",os.getpid(),TARGET_URL);kick_daemon()
try:
 n=0
 for _,_,ps in target_tabs():
  for p in ps:
   q=decode(p)
   if q and str(q["id"]) not in seen:seen.add(str(q["id"]));n+=1
 STATE.write_text(json.dumps({"schema":4,"seen":list(seen)[-5000:]}));log("PRIMED",n,"READY")
except Exception as e:log("PRIME_ERROR",type(e).__name__,str(e))
while True:
 try:
  rows=target_tabs()
  if rows:
   wi,ti,ps=rows[0]
   for p in ps:
    q=decode(p)
    if not q:continue
    rid=str(q["id"])
    if rid in seen:continue
    log("CAPTURE",rid,wi,ti);res=local(q)
    msg="CHAT_LOCAL_RESULT "+rid+"\n"+json.dumps(res,ensure_ascii=False)
    sr=send_to_tab(wi,ti,msg);log("SEND",rid,sr)
    if sr=="SCHEDULED":
     seen.add(rid);STATE.write_text(json.dumps({"schema":4,"seen":list(seen)[-5000:]}))
    break
 except Exception as e:log("LOOP_ERROR",type(e).__name__,str(e))
 time.sleep(.8)
